Reference implementation (Python 3.12+):
```python
from collections import deque

def topological_order(graph):
    indegree = {v: 0 for v in graph}
    for v in graph:
        for u in graph[v]: indegree[u] = indegree.get(u, 0) + 1
    q = deque(v for v, degree in indegree.items() if degree == 0); order=[]
    while q:
        v=q.popleft(); order.append(v)
        for u in graph[v]:
            indegree[u] -= 1
            if indegree[u] == 0: q.append(u)
    return order if len(order) == len(indegree) else None

assert topological_order({"a":["c"],"b":["c"],"c":[]}) is not None
assert topological_order({"a":["b"],"b":["a"]}) is None
